import glob

THRESHOLD = 100

vips = []
for path in glob.glob("members/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            name, points = line.strip().split(",")
            if int(points) > THRESHOLD:
                vips.append(name)
for name in sorted(vips):
    print(name)
